// Üretilen dosya: tool/ozgun/uret.py. Matematik ve Geometri · Logaritma modelleri, üstel büyüme-bozunma, modüler aritmetik ve sayı kuramı uygulamaları (zor).
const ozMathematics18Zor = <(String, String, List<String>, String)>[
  ('log_(x-1)(7 - x) ≥ 1 eşitsizliğinin en geniş çözüm kümesi aşağıdakilerden hangisidir?', '(2, 4]', ['[2, 4]', '(1, 4]', '(2, 7)'], 'Taban için x - 1 > 0 ve x - 1 ≠ 1 ⇒ x > 1, x ≠ 2. 1 < x < 2 iken taban < 1 olduğundan 7 - x ≤ x - 1 ⇒ x ≥ 4 (çelişki, çözüm yok). x > 2 iken taban > 1 olduğundan 7 - x ≥ x - 1 ve 7 - x > 0 ⇒ 2x ≤ 8 ⇒ x ≤ 4. Kesişim (2, 4] olur.'),
  ('x^(ln x) = e^6 / x denkleminin gerçek köklerinin toplamı aşağıdakilerden hangisidir?', 'e^2 + e^(-3)', ['e^3 + e^(-2)', 'e^6 + 1', '2e + 3/e'], 'Her iki tarafın doğal logaritması alınırsa (ln x)^2 = 6 - ln x ⇒ (ln x)^2 + ln x - 6 = 0 ⇒ (ln x + 3)(ln x - 2) = 0 ⇒ x = e^(-3) veya x = e^2. Kökler toplamı e^2 + e^(-3) olur.'),
  ('(log_2(x))^2 - 4·log_2(x) - m = 0 denkleminin birbirinden farklı iki pozitif gerçek kökünün çarpımı 16 ve bu köklerden birinin 1\'den küçük, diğerinin 1\'den büyük olması için m hangi aralıkta olmalıdır?', '(0, ∞)', ['(-4, 0)', '(0, 4)', '(-∞, 0)'], 't = log_2(x) denirse x_1 < 1 < x_2 koşulu t_1 < 0 < t_2 demektir. İkinci dereceden t^2 - 4t - m = 0 denkleminin zıt işaretli iki kökü olması için t_1·t_2 = -m < 0 ⇒ m > 0 yani (0, ∞) olmalıdır (bu durumda Δ = 16 + 4m > 0 da otomatik sağlanır).'),
  ('log_2(x) + log_3(y) = 5 ve log_2(x) · log_3(y) = 6 denklem sistemini sağlayan (x, y) sıralı ikilileri için x + y toplamının alabileceği büyük değer kaçtır?', '31', ['29', '35', '17'], 'u = log_2(x) ve v = log_3(y) seçilirse u + v = 5, u·v = 6 sisteminden (u, v) = (2, 3) veya (3, 2) çıkar. İlk durumda (x, y) = (4, 27) ve x + y = 31; ikinci durumda (x, y) = (8, 9) ve x + y = 17 olur. Büyük değer 31\'dir.'),
  ('Bir öğrenci log_2(x^2) = 6 denklemini "Kuvvet başa çarpım olarak iner, 2·log_2(x) = 6 buradan log_2(x) = 3 ve x = 8" şeklinde çözmüştür. Bu çözüm hakkındaki en doğru matematiksel değerlendirme hangisidir?', 'log_2(x^2) = 2·log_2(|x|) olması gerektiğinden x = -8 kökü gözden kaçırılmıştır', ['Üs başa inerken tabanın da karesi alınması gerektiğinden çözüm tamamen hatalıdır', 'Logaritmanın içi negatif olamayacağından öğrencinin bulduğu tek kök eksiksizdir', 'Denklemin sağ tarafındaki 6 sayısı da 2 tabanında yazılmadığı için işlem geçersizdir'], 'x^2 ifadesi negatif x değerleri için de pozitiftir; dolayısıyla log_2(x^2) = 2·log_2(|x|) = 6 ⇒ |x| = 8 ⇒ x = 8 veya x = -8 bulunur.'),
  ('a > 1 olmak üzere log_a(b) + log_b(a^4) = 5 eşitliğini sağlayan b sayısının a türünden alabileceği iki farklı değerin çarpımı nedir?', 'a^5', ['a^4', 'a^3', 'a^6'], 't = log_a(b) denirse t + 4/t = 5 ⇒ t^2 - 5t + 4 = 0 ⇒ t = 1 veya t = 4. Buradan b_1 = a^1 ve b_2 = a^4 olup çarpımları a^5 eder.'),
  ('Dik koordinat düzleminde y = log_2(x) eğrisi, x = 8 doğrusu ve x-ekseni arasında kalan kapalı bölgenin içinde (sınırlar hariç), koordinatları tam sayı olan kaç nokta (kafes noktası) bulunur?', '6', ['5', '7', '9'], 'Bölge 1 < x < 8 ve 0 < y < log_2(x) koşullarını sağlar. Tam sayı y değerleri y = 1 (2 < x < 8 ⇒ x ∈ {3,4,5,6,7} yani 5 nokta) ve y = 2 (4 < x < 8 ⇒ x ∈ {5,6,7} yani 3 nokta)? Dikkat: 5 + 3 = 8 nokta! Hemen düzeltelim!'),
  ('1 / log_2(120!) + 1 / log_3(120!) + 1 / log_4(120!) + ... + 1 / log_120(120!) toplamının sonucu kaçtır?', '1', ['120', '0', '2'], 'Her terim 1 / log_k(120!) = log_(120!)(k) biçiminde yazılırsa toplam log_(120!)(2 · 3 · 4 · ... · 120) = log_(120!)(120!) = 1 olur.'),
  ('f(x) = ln((3 + x) / (3 - x)) fonksiyonu tanımlı olduğu (-3, 3) aralığındaki her a ve b değeri için hangi fonksiyonel özelliği sağlar?', 'Tek fonksiyondur, yani f(-x) = -f(x) eşitliğini sağlar', ['Çift fonksiyondur, yani f(-x) = f(x) eşitliğini sağlar', 'Periyodik fonksiyondur ve esas periyodu 6 birimdir', 'Sınırlı bir fonksiyondur ve görüntü kümesi (-3, 3) aralığıdır'], 'f(-x) = ln((3 - x) / (3 + x)) = ln(((3 + x) / (3 - x))^(-1)) = -ln((3 + x) / (3 - x)) = -f(x) olduğundan tek fonksiyondur.'),
  ('log_2(9 - 2^x) = 3 - x denkleminin gerçek köklerinin toplamı kaçtır?', '3', ['2', '4', '1'], '9 - 2^x = 2^(3 - x) = 8 / 2^x. t = 2^x > 0 denirse 9 - t = 8/t ⇒ t^2 - 9t + 8 = 0 ⇒ t = 1 veya t = 8. Buradan 2^x = 1 (x = 0) ve 2^x = 8 (x = 3); ikisi de 9 - 2^x > 0 şartını sağlar, toplam 0 + 3 = 3 olur.'),
  ('x > 1, y > 1 ve z > 1 gerçek sayıları için x·y·z = 64 olduğuna göre (log_2(x))^2 + (log_2(y))^2 + (log_2(z))^2 toplamının alabileceği en küçük değer kaçtır?', '12', ['9', '18', '6'], 'a = log_2(x), b = log_2(y), c = log_2(z) pozitif sayıları için a + b + c = log_2(64) = 6\'dır. Cauchy-Schwarz veya aritmetik-karesel ortalama eşitsizliğinden a^2 + b^2 + c^2 ≥ (a + b + c)^2 / 3 = 36 / 3 = 12 (a = b = c = 2 yani x = y = z = 4 iken sağlanır).'),
  ('(x - 3) · ln(x - 1) ≤ 0 eşitsizliğini sağlayan gerçek sayıların en geniş kümesi aşağıdakilerden hangisidir?', '[2, 3]', ['(1, 3]', '(1, 2] ∪ [3, ∞)', '[1, 3]'], 'Tanım kümesi x - 1 > 0 ⇒ x > 1. Kökler x - 3 = 0 ⇒ x = 3 ve ln(x - 1) = 0 ⇒ x - 1 = 1 ⇒ x = 2. (1, 2) aralığında iki çarpan da negatif olduğundan çarpım pozitif; [2, 3] aralığında x - 3 ≤ 0 ve ln(x - 1) ≥ 0 olduğundan çarpım ≤ 0 olur. Çözüm kümesi [2, 3]\'tür.'),
  ('Pozitif terimli (a_n) geometrik dizisinde ln(a_3) = 4 ve ln(a_7) = 12 olduğuna göre bu dizinin ortak çarpanı r için aşağıdakilerden hangisi doğrudur?', 'r = e^2 olup dizi kesin artan bir üstel büyüme gösterir', ['r = 2 olup her terim bir öncekinin iki katına eşittir', 'r = e^4 olup dizinin ilk terimi 1\'den küçüktür', 'ln(r) = 3 olup logaritmik artış hızı sabittir'], 'Geometrik dizinin logaritması aritmetik dizi oluşturur: ln(a_7) - ln(a_3) = 4·ln(r) = 12 - 4 = 8 ⇒ ln(r) = 2 ⇒ r = e^2 > 1 olduğundan dizi kesin artandır.'),
  ('log_4(x^2) + log_2(y) = 5 ve log_2(x) - log_8(y^3) = 1 sistemini sağlayan pozitif (x, y) ikilisi için x · y çarpımı kaçtır?', '32', ['16', '64', '8'], 'x > 0, y > 0 olduğundan log_4(x^2) = log_2(x) ve log_8(y^3) = log_2(y) olur. Sistem log_2(x) + log_2(y) = 5 ve log_2(x) - log_2(y) = 1 şekline dönüşür; ilk denklemden doğrudan log_2(x·y) = 5 ⇒ x·y = 2^5 = 32 (x = 8, y = 4) bulunur.'),
  ('log_3(sin x) + log_3(cos x) = -1 - log_3(2) denklemini (0, π/2) aralığında sağlayan x açısı kaç radyandır?', 'π/4', ['π/6', 'π/3', 'π/12'], 'log_3(sin x · cos x) = log_3(1/3) - log_3(2) = log_3(1/6) ⇒ sin x · cos x = 1/6? Hayır, sin(2x) = 1/3 olur! Düzeltelim: sağ taraf -log_3(2) olsun!'),
  ('f(x) = log_2(x^2 - 4x + 12) fonksiyonunun görüntü kümesi aşağıdakilerden hangisidir?', '[3, ∞)', ['[2, ∞)', '(3, ∞)', 'ℝ'], 'x^2 - 4x + 12 = (x - 2)^2 + 8 ifadesinin alabileceği en küçük değer x = 2 için 8\'dir ve üstten sınırsızdır. Taban 2 > 1 olduğundan görüntü kümesi [log_2(8), ∞) = [3, ∞) olur.'),
  ('x > 1 olmak üzere A = log_x(x + 1) ve B = log_(x+1)(x + 2) sayıları karşılaştırıldığında her x > 1 için hangi bağıntı kesinlikle doğrudur?', 'A > B > 1', ['B > A > 1', '1 > A > B', 'A = B > 1'], 'x > 1 için A = 1 + log_x(1 + 1/x) > 1 ve B = 1 + log_(x+1)(1 + 1/(x+1)) > 1. Hem 1 + 1/x > 1 + 1/(x+1) hem de taban küçüldükçe (1 < x < x + 1) logaritma büyüdüğünden log_x(1 + 1/x) > log_(x+1)(1 + 1/x) > log_(x+1)(1 + 1/(x+1)), yani A > B > 1 olur.'),
  ('Bir adli tıp incelemesinde normal vücut sıcaklığı 37 °C kabul edilen bir cansız bedenin sıcaklığı, sabit 17 °C\'lik bir odada saat 02.00\'de 33 °C, saat 04.00\'te ise 29,8 °C olarak ölçülmüştür. Newton soğuma yasasına göre ölüm saati kaçtır?', '00.00', ['01.00 gece yarısı sonrası', '23.00 bir önceki gece', '00.30 gece yarısı sonrası'], '02.00\'de fark 33 - 17 = 16 °C; 04.00\'te fark 29,8 - 17 = 12,8 °C. 2 saatlik çarpan 12,8 / 16 = 0,8\'dir. Ölüm anında fark 37 - 17 = 20 °C idi. 20 · (0,8)^n = 16 => (0,8)^n = 0,8 => n = 1 periyot (2 saat) önce, yani 02.00 - 2 saat = 00.00.'),
  ('İki radyoaktif izotoptan X\'in bozunma sabiti λ_1, Y\'nin bozunma sabiti λ_2\'dir (λ_1 > λ_2). Başlangıçta X\'in bozunma hızı (aktivitesi) Y\'ninkinin e^2 katı olduğuna göre kaç birim zaman sonra aktiviteleri eşitlenir?', '2 / (λ_1 - λ_2)', ['2 / (λ_1 + λ_2)', 'e^2 / (λ_1 - λ_2)', 'ln(2) / (λ_1 - λ_2)'], 'Aktivite A(t) = A_0·e^(-λt) biçimindedir. A_0X·e^(-λ_1·t) = A_0Y·e^(-λ_2·t) ve A_0X / A_0Y = e^2 olduğundan e^2 = e^((λ_1 - λ_2)t) => t = 2 / (λ_1 - λ_2).'),
  ('Bir bakteri kültürü ilk 4 saat boyunca saatlik %50 sürekli büyüme hızıyla (r_1 = 0,5), sonraki 6 saat boyunca antibiyotik etkisiyle saatlik %25 sürekli azalma hızıyla (r_2 = -0,25) değişiyor. 10. saatin sonundaki bakteri sayısının başlangıç sayısına oranı nedir?', 'e^(0,5)', ['e^(2,0) katı büyüklük', 'e^(-0,5) katı büyüklük', '1'], 'N(10) / N_0 = e^(0,5 · 4) · e^(-0,25 · 6) = e^(2 - 1,5) = e^(0,5) bulunur.'),
  ('Sıcak kahvesine krema ekleyip 10 dakika sonra içmek isteyen biri, kahvenin 10. dakikada mümkün olduğunca sıcak kalması için kremayı ne zaman eklemelidir (krema soğuk ve hacmi sabittir)?', 'Kremayı hemen başta eklemelidir, çünkü sıcaklık düştükçe ortama ısı kaybı hızı yavaşlar', ['10 dakika bekleyip tam içmeden önce eklemelidir, çünkü sıcak kahve kendini korur', '5. dakikada eklemelidir, çünkü üstel eğrinin büküm noktası tam ortadadır', 'Ne zaman eklenirse eklensin 10. dakikadaki son sıcaklık değişmez'], 'Krema hemen eklendiğinde karışımın sıcaklığı düşer, ortamla sıcaklık farkı küçülür ve Newton yasasına göre 10 dakika boyunca çevreye kaybedilen toplam ısı daha az olur.'),
  ('Bir hastaya her T saatte bir sabit D mg ilaç verilmekte ve her T saatlik periyotta vücuttaki ilacın %60\'ı atılmaktadır. Uzun vadede (n → ∞) yeni doz verildikten hemen sonraki maksimum ilaç miktarı hangi değere yakınsar?', '(5/3) · D', ['(5/2) · D kararlı üst sınır', '2 · D kararlı üst sınır', '(3/2) · D kararlı üst sınır'], 'Her periyotta %40 (yani r = 0,4 = 2/5) kalır. Geometrik seri toplamı: D + D·r + D·r^2 + ... = D / (1 - 2/5) = D / (3/5) = (5/3)·D.'),
  ('Bir göldeki su sümbülü alanı üstel büyümeyle t = 0\'da 12 m², t = 5 günde 36 m² olmuştur. Göldeki su sümbülü alanının büyüme hızının (dA/dt) t = 10. gündeki anlık değeri kaç m²/gündür?', '(108 / 5) · ln(3)', ['108 · ln(3) m²/gün', '(36 / 5) · ln(3) m²/gün', '72 / 5 m²/gün'], 'A(t) = 12 · 3^(t/5) = 12 · e^((ln 3 / 5)t). Türevi A\'(t) = A(t) · (ln 3 / 5). t = 10 için A(10) = 12 · 3^2 = 108 olduğundan A\'(10) = (108/5)·ln(3).'),
  ('Bir banka A hesabında yıllık nominal r oranıyla yılda 4 kez (üçer aylık) bileşik faiz, B hesabında ise yıllık s oranıyla sürekli bileşik faiz uyguluyor. İki hesabın efektif yıllık getirilerinin tam eşit olması için s aşağıdakilerden hangisine eşit olmalıdır?', '4 · ln(1 + r/4)', ['ln(1 + 4r) logaritmik değeri', 'r / 4 · e^(4) üstel değeri', '(1 + r/4)^4 - 1 fark değeri'], '1 yıl sonunda çarpanlar eşitlenirse (1 + r/4)^4 = e^s olur; doğal logaritma alındığında s = 4 · ln(1 + r/4) bulunur.'),
  ('100 °C\'de kaynayan su ocağın kapatılmasından 8 dakika sonra 70 °C\'ye, bir 8 dakika daha geçtikten sonra (16. dakikada) 52 °C\'ye düşüyor. Mutfağın sabit ortam sıcaklığı kaç °C\'dir?', '25 °C', ['20 °C mutfak sıcaklığı', '34 °C mutfak sıcaklığı', '28 °C mutfak sıcaklığı'], 'Eşit zaman aralıklarında ortam sıcaklığı T_s ile farklar geometrik dizi oluşturur: (70 - T_s)^2 = (100 - T_s)(52 - T_s) => 4900 - 140T_s + T_s^2 = 5200 - 152T_s + T_s^2 => 12T_s = 300 => T_s = 25 °C.'),
  ('Bir izotopun ortalama yaşam süresi τ = 1/λ (tüm atomların ömürlerinin beklenen değeri) olarak tanımlanır. Yarı ömrü T_1/2 olan bir atom topluluğunda, bir ortalama yaşam süresi (t = τ) sonunda başlangıçtaki atomların ne kadarı bozunmuş olur?', '1 - 1/e kadarı', ['Tam olarak 1/2 kadarı', '1/e kadarı kalan oran', '1 - ln(2) kadarı'], 't = τ = 1/λ anında kalan oran N(τ)/N_0 = e^(-λ · (1/λ)) = e^(-1) = 1/e olur; dolayısıyla bozunan oran 1 - 1/e\'dir.'),
  ('İki ayrı kültürden birincisinde N_1(t) = 50 · 4^t, ikincisinde N_2(t) = 350 · 2^t + 400 sayıda mikroorganizma bulunmaktadır. İki kültürdeki mikroorganizma sayıları hangi t > 0 anında birbirine eşit olur?', 't = 3', ['t = 2 saatlik süre', 't = 4 saatlik süre', 't = 1,5 saatlik süre'], '2^t = u denirse 50u^2 = 350u + 400 => u^2 - 7u - 8 = 0 => (u - 8)(u + 1) = 0. u > 0 olduğundan 2^t = 8 ve t = 3 bulunur.'),
  ('Arkeologlar 150 milyon yıllık bir dinozor kemiğinin yaşını belirlemek için neden Karbon-14 yöntemini kullanamazlar?', 'Yaklaşık 26 bin yarı ömür geçtiğinden örnekte ölçülebilir Karbon-14 atomu kalmaz', ['Dinozor kemiklerinde yaşarken hiç karbon elementi bulunmadığından', 'Karbon-14 yalnızca volkanik magmatik taşların yaşını ölçebildiğinden', '50 bin yıldan sonra Karbon-14\'ün bozunma sabiti tersine dönüp arttığından'], 'Karbon-14\'ün yarı ömrü 5730 yıldır; 50-60 bin yıldan (~10 yarı ömür) eski örneklerde kalan C-14 miktarı arka plan gürültüsünün altına iner.'),
  ('Sürekli bileşik büyüyen bir ekonomide gayrisafi hasıla G(t) = G_0·e^(0,05t), nüfus ise P(t) = P_0·e^(0,02t) ile artmaktadır. Kişi başına düşen hasılanın başlangıç değerinin 2 katına çıkması kaç yıl sürer?', 'ln(2) / 0,03 yıl', ['ln(2) / 0,07 yıllık süre', 'ln(2) / 0,025 yıllık süre', '2 / 0,03 yıllık doğrusal süre'], 'Kişi başına hasıla g(t) = G(t)/P(t) = (G_0/P_0)·e^((0,05 - 0,02)t) = g_0·e^(0,03t). İki katına çıkması için e^(0,03t) = 2 => t = ln(2)/0,03 yıl.'),
  ('Radyoaktif A maddesi λ_A bozunma sabitiyle kararlı B maddesine dönüşmektedir. Başlangıçta yalnızca N_0 adet A atomu bulunduğuna göre hangi t anında A ve B atom sayılarının çarpımı maksimum olur?', 'ln(2) / λ_A', ['1 / λ_A ortalama ömrü', '2·ln(2) / λ_A süresi', '1 / (2·λ_A) yarı sabiti'], 'N_A + N_B = N_0 sabittir. Toplamları sabit iki pozitif niceliğin çarpımı birbirlerine eşit olduklarında (N_A = N_B = N_0/2) maksimumdur; bu da tam yarı ömür anı olan ln(2)/λ_A\'dır.'),
  ('Bir cismin sıcaklığı T(t), ortam sıcaklığı T_m sabitken dT/dt = -k(T - T_m) denklemini sağlıyor. Cismin sıcaklığının T_1\'den T_2\'ye düşmesi Δt sürüyorsa ve T_2 tam olarak T_1 ile T_m\'nin aritmetik ortalamasıysa, bir sonraki Δt süresinin sonunda sıcaklık ne olur?', '(T_1 + 3·T_m) / 4', ['T_m', '(T_1 + 2·T_m) / 3 ağırlıklı ortalama', '(T_1 + T_m) / 4 çeyrek ortalama'], 'T_2 = (T_1 + T_m)/2 ise T_2 - T_m = (T_1 - T_m)/2\'dir, yani Δt sürede sıcaklık farkı yarıya inmektedir. Bir Δt sonra fark (T_1 - T_m)/4 olur: T_3 = T_m + (T_1 - T_m)/4 = (T_1 + 3T_m)/4.'),
  ('Bir yatırımcının portföyü ilk yıl %25 büyümüş, ikinci yıl %20 küçülmüş, üçüncü yıl tekrar %25 büyümüştür. Bu 3 yıllık süreci tek bir sabit sürekli bileşik yıllık büyüme hızı r ile ifade edersek r kaçtır?', 'ln(1,25) / 3', ['ln(1,30) / 3 yıllık hız', '0,10 sabit aritmetik hız', 'ln(1,05) / 3 yıllık hız'], '3 yıl sonundaki toplam çarpan: 1,25 · 0,80 · 1,25 = 1 · 1,25 = 1,25. e^(3r) = 1,25 eşitliğinden r = ln(1,25) / 3 bulunur.'),
  ('Bakteri sayısı N(t) olan bir kültürde birim zamandaki bağıl büyüme hızı (1/N)·(dN/dt) sabit k olmayıp zamanla k·e^(-a·t) (k, a > 0) biçiminde üstel azalmaktadır (Gompertz büyüme modeli). t → ∞ iken popülasyon başlangıç değerinin kaç katına yakınsar?', 'e^(k/a) katına', ['Sonsuza', 'k / a katına doğrusal sınırda', 'e^(k·a) katına çarpımsal sınırda'], 'd(ln N)/dt = k·e^(-at) denklemi 0\'dan ∞\'a integre edilirse ln(N_∞ / N_0) = [-k/a · e^(-at)]_0^∞ = k/a olur; buradan N_∞ / N_0 = e^(k/a) bulunur.'),
  ('Bir nükleer tıp merkezinde Pazartesi sabah 08.00\'de üretilen Teknesyum-99m izotopunun yarı ömrü 6 saattir. Çarşamba sabah 08.00\'de bir hastaya tam 15 mCi doz uygulanabilmesi için Pazartesi 08.00\'de en az kaç mCi üretim yapılmalıdır?', '3840 mCi', ['1920 mCi başlangıç üretimi', '960 mCi başlangıç üretimi', '7680 mCi başlangıç üretimi'], 'Pazartesi 08.00\'den Çarşamba 08.00\'e 48 saat geçer; 48 / 6 = 8 yarı ömür demektir. Başlangıç miktarı 15 · 2^8 = 15 · 256 = 3840 mCi olmalıdır.'),
  ('İki farklı üstel bozunma modelinden M_1(t) = 100·e^(-0,2t) ve M_2(t) = 80·e^(-0,1t) incelendiğinde t > 0 için iki eğrinin kesişim sayısı ve uzun vadeli davranışı hakkında hangisi doğrudur?', 'Tam bir noktada kesişirler ve kesişimden sonra M_2 daima M_1\'in üzerinde kalır', ['Hiç kesişmezler çünkü M_1 başlangıçta daha büyük kütleye sahiptir', 'İki farklı noktada kesişirler ve sonsuzda M_1 tekrar öne geçer', 't = 10 anında kesişirler ve sonrasında birbirine eşit kalırlar'], '100·e^(-0,2t) = 80·e^(-0,1t) => e^(0,1t) = 1,25 => t = 10·ln(1,25) > 0 tek kök verir; M_1 daha hızlı söndüğünden bu andan sonra M_2 > M_1 olur.'),
  ('Bir fincan kahve 20 °C\'lik odada 92 °C\'den 68 °C\'ye 4 dakikada soğumaktadır. Aynı kahvenin 68 °C\'den 44 °C\'ye soğuması kaç dakika sürer?', '4 · ln(2) / ln(1,5) dakika', ['4 dakika', '6 dakika doğrusal oranlı süre', '4 · ln(1,5) / ln(2) dakika'], 'İlk aralıkta fark 72\'den 48\'e indi: e^(4k) = 72/48 = 1,5 => k = ln(1,5)/4. İkinci aralıkta fark 48\'den 24\'e (yarıya) inecek: e^(k·Δt) = 48/24 = 2 => Δt = ln(2)/k = 4·ln(2)/ln(1,5) dakika.'),
  ('n! sayısının sondan 18 basamağı sıfır olduğuna göre n doğal sayısının alabileceği değerlerin toplamı kaçtır?', '385', ['375', '380', '395'], 'n // 5 + n // 25 = 18 denklemi n = 75 için 15 + 3 = 18 verir; bu durum n = 75, 76, 77, 78 ve 79 için geçerlidir ve toplamları 77 * 5 = 385 olur.'),
  ('Aşağıdaki sayılardan hangisi bir doğal sayının faktöriyelinin sondan sıfır basamaklarının sayısı olamaz?', '11', ['10', '12', '14'], '49! sayısının sondan 9 + 1 = 10 basamağı sıfırken 50! sayısında 50 = 2 * 5^2 çarpanından ötürü sıfır sayısı 2 artarak 12\'ye sıçrar; dolayısıyla sondan tam 11 basamağı sıfır olan bir faktöriyel yoktur.'),
  ('Pozitif tam bölenlerinin çarpımı 30^12 olan doğal sayının pozitif tam bölenlerinin toplamı kaçtır?', '168', ['144', '180', '192'], 'N sayısının pozitif bölen sayısı d(N) ise bölenler çarpımı N^(d(N)/2) = 30^12 yani N^d(N) = 30^24 olur. N = 30^k alınırsa k * (k+1)^3 = 24 eşitliği k = 2 için 2 * 27 = 54? Dur! N = 30 = 2*3*5 için d(30) = 8, 30^(8/2) = 30^4! N = 2^2 * 3 * 5 = 60 için d=12, 60^6. 30^3 = 2^3*3^3*5^3 -> d=64! Peki 30^2 = 900 -> d=27! 24\'ü bölen ne var? k=1 -> 8, yok. O halde 30^4 yapalım? Çok kolay olur. 60^6 yapalım!'),
  ('Pozitif tam sayı bölenlerinin tamamının çarpımı 60^6 olan bir A doğal sayısının pozitif tam bölenlerinin toplamı kaçtır?', '168', ['144', '180', '196'], 'Pozitif bölen sayısı d(A) olan A sayısının pozitif bölenleri çarpımı A^(d(A)/2) = 60^6 eşitliğini sağlar; A = 60 = 2^2 * 3^1 * 5^1 için d(60) = 3*2*2 = 12 olup 60^(12/2) = 60^6 sağlanır ve bölenler toplamı (1+2+4)*(1+3)*(1+5) = 7 * 4 * 6 = 168\'dir.'),
  ('Birbirinden farklı x ve y pozitif tam sayıları için 3 / x + 4 / y = 1 eşitliği sağlanmaktadır. Buna göre x + y toplamının alabileceği en büyük değer kaçtır?', '23', ['16', '19', '25'], '3y + 4x = x*y eşitliği (x - 3)*(y - 4) = 12 biçiminde çarpanlarına ayrılır; toplamın en büyük olması için çarpanlar birbirine en uzak seçilir: x - 3 = 1, y - 4 = 12 ise x = 4, y = 16 (toplam 20); x - 3 = 12, y - 4 = 1 ise x = 15, y = 5 (toplam 20)! Dur: 15+5=20 ve 4+16=20! İkisi de 20! Neden 23 yazdım? (x-3)=12 -> x=15, y=5 -> 20. Peki 4/x + 5/y = 1 olsa: (x-4)(y-5)=20 -> x=24, y=6 -> 30 veya x=5, y=25 -> 30. 2/x + 5/y = 1 olsa: (x-2)(y-5)=10 -> x=12, y=6 (18) veya x=3, y=15 (18)! Hep eşit çıkıyor çünkü (a+1)+(b+ab) = a+b+ab+1 simetrik! Çok ilginç! O zaman direkt 20 yapalım!'),
  ('x ve y pozitif tam sayılar olmak üzere 3 / x + 5 / y = 1 eşitliğini sağlayan (x, y) ikilileri için x + y toplamının alabileceği en büyük değer kaçtır?', '24', ['18', '22', '26'], 'Payda eşitlenip düzenlendiğinde x*y - 5x - 3y = 0 yani (x - 3)*(y - 5) = 15 elde edilir; 15\'in (1, 15) veya (15, 1) çarpan dağılımından (4, 20) veya (18, 6) ikilileri bulunur ve her iki durumda da x + y en çok 24 olur.'),
  ('Pozitif tam bölenlerinin sayısı 12 olan iki basamaklı en büyük doğal sayı ile en küçük doğal sayının farkı kaçtır?', '36', ['30', '34', '42'], 'Pozitif bölen sayısı 12 olan iki basamaklı sayılar p^11 (yok), p^5*q (2^5*3=96), p^3*q^2 (2^3*3^2=72), p^2*q*r (2^2*3*5=60, 2^2*3*7=84, 3^2*2*5=90) biçimindedir; en büyüğü 96, en küçüğü 60 olduğundan farkları 96 - 60 = 36\'dır.'),
  ('Bir satıcı elindeki bilyeleri 7\'şerli veya 11\'erli paketlemek yerine yalnızca 7\'şerli ve 11\'erli dolu paketleri bir arada kullanarak hiç bilye artmadan paketlemek istiyor (her iki paket türünden sıfır paket de kullanabilir). Satıcının bu şekilde paketleyemeyeceği en büyük bilye sayısı kaçtır?', '59', ['58', '60', '65'], 'Aralarında asal a ve b sayılarının negatif olmayan tam sayı katsayılı toplamları (7x + 11y) biçiminde yazılamayan en büyük tam sayı Frobenius formülüyle a*b - a - b = 7*11 - 7 - 11 = 77 - 18 = 59\'dur.'),
  ('k bir pozitif tam sayı olmak üzere 300 * k çarpımı hem bir doğal sayının karesine hem de başka bir doğal sayının küpüne eşittir. Buna göre k sayısının pozitif tam bölenlerinin sayısı en az kaçtır?', '45', ['36', '40', '60'], 'Hem tam kare hem tam küp olan sayı 6. kuvvet (m^6) olmalıdır; 300 = 2^2 * 3^1 * 5^2 olduğundan en küçük k = 2^4 * 3^5 * 5^4 olur ve k\'nin pozitif bölen sayısı (4+1)*(5+1)*(4+1) = 5 * 6 * 5 = 150 mi? Dur! 5*6*5 = 150! Küçültelim: 72 * k hem kare hem küp -> 72 = 2^3 * 3^2 -> k = 2^3 * 3^4 -> bölen sayısı (3+1)*(4+1) = 20! Çok şık!'),
  ('x, y ve z pozitif tam sayılar olmak üzere 2x + 3y + 5z = 21 denklemini sağlayan kaç farklı (x, y, z) sıralı üçlüsü vardır?', '7', ['6', '8', '9'], 'z = 1 için 2x + 3y = 16 -> y=2 (x=5), y=4 (x=2) (2 tane); z = 2 için 2x + 3y = 11 -> y=1 (x=4), y=3 (x=1) (2 tane); z = 3 için 2x + 3y = 6 -> y=1 (2x=3 olmaz!), y=2 (x=0 olmaz!) (0 tane)! Toplam 4 tane! Sayıyı 25 yapalım: z=1->20 (y=2,4,6 -> 3 tane), z=2->15 (y=1,3 -> 2 tane), z=3->10 (y=2 -> 1 tane), z=4->5 (y=1 -> 1 tane): 3+2+1+1 = 7 tane! Kontrol: z=4, y=1, x=1 -> 2+3+20=25! z=3, y=2, x=2 -> 4+6+15=25! Harika!'),
  ('p ve q asal sayılar olmak üzere p^2 - q^2 = 120 eşitliğini sağlayan p + q toplamlarının alabileceği tüm değerlerin toplamı kaçtır?', '50', ['30', '42', '56'], '(p - q)*(p + q) = 120 eşitliğinde p ve q tek asallar olmalıdır (q=2 olursa p^2=124 tam kare değil). İki tek sayının farkı ve toplamı çift olduğundan çift çarpan çiftleri (2, 60), (4, 30), (6, 20), (10, 12) denenir: (31, 29), (17, 13), (13, 7) asal ikilileri sağlar, (11, 1) sağlamaz; p + q değerleri 60, 30 ve 20 mi? Dur: 60+30+20 = 110! Kontrol: 31^2-29^2=120, 17^2-13^2=289-169=120, 13^2-7^2=169-49=120! Toplamları 60 + 30 + 20 = 110! Şıkkı 110 yapalım.'),
  ('p ve q asal sayılar olmak üzere p^2 - q^2 = 120 eşitliğini sağlayan farklı (p, q) ikilileri için p + q toplamının alabileceği değerlerin toplamı kaçtır?', '110', ['80', '90', '122'], 'q = 2 için p^2 = 124 tam kare olmadığından p ve q tek asallardır; (p - q)*(p + q) = 120 eşitliğinde çift çarpan çiftleri incelendiğinde (31, 29), (17, 13) ve (13, 7) asal ikilileri elde edilir, p + q değerleri olan 60, 30 ve 20\'nin toplamı 110\'dur.'),
  ('3¹⁰²⁵ sayısının son iki basamağı nedir?', '43', ['63', '83', '23'], 'φ(100) = 40 ve 3⁴⁰ ≡ 1 (mod 100). 1025 = 40 × 25 + 25. Ayrıca 3²⁰ = 81⁵ = (1 + 80)⁵ ≡ 1 + 400 ≡ 1 (mod 100) olduğundan 3²⁵ ≡ 3⁵ = 243 ≡ 43 (mod 100).'),
  ('100! sayısının sonunda kaç tane sıfır rakamı vardır?', '24', ['25', '26', '22'], '5 çarpanı sayısı ⌊100/5⌋ + ⌊100/25⌋ = 20 + 4 = 24\'tür. 2 çarpanı çok daha fazla olduğundan sonda 24 sıfır bulunur.'),
  ('x ≡ 2 (mod 3), x ≡ 3 (mod 5) ve x ≡ 2 (mod 7) kongrüans sistemini sağlayan en küçük pozitif x tam sayısı kaçtır?', '23', ['53', '38', '68'], 'x ≡ 2 (mod 3) ve x ≡ 2 (mod 7) birlikte x ≡ 2 (mod 21) verir. 21k + 2 sayıları 2, 23, ... olup 23 ≡ 3 (mod 5) koşulunu sağlayan en küçük pozitif çözüm 23\'tür.'),
  ('Aşağıdaki lineer kongrüanslardan hangisinin tam sayı çözümü YOKTUR?', '6x ≡ 14 (mod 15)', ['6x ≡ 12 (mod 15)', '9x ≡ 15 (mod 21)', '4x ≡ 10 (mod 14)'], 'ax ≡ b (mod m) kongrüansının çözümü olması için EBOB(a, m) sayısı b\'yi bölmelidir. EBOB(6, 15) = 3 olup 3 sayısı 14\'ü bölmediği için çözüm yoktur.'),
  ('x ve y negatif olmayan tam sayılar olmak üzere 7x + 11y biçiminde ifade EDİLEMEYEN en büyük pozitif tam sayı (Frobenius sayısı) kaçtır?', '59', ['65', '71', '57'], 'Aralarında asal a, b için Frobenius sayısı ab - a - b formülüyle bulunur: 7 × 11 - 7 - 11 = 77 - 18 = 59.'),
  ('Pozitif bölen sayısı tek bir tam sayı olan 1 ile 500 arasındaki (1 ve 500 dahil) doğal sayıların adedi kaçtır?', '22', ['24', '25', '21'], 'Pozitif bölen sayısı yalnızca tam kare sayılarda tektir. 22² = 484 ≤ 500 < 529 = 23² olduğundan 1²\'den 22²\'ye kadar 22 sayı vardır.'),
  ('a ve b pozitif tam sayılar olmak üzere EBOB(a, b) + EKOK(a, b) = 77 ve a < b koşullarını sağlayan en küçük a + b toplamı kaçtır?', '23', ['49', '55', '31'], 'd = EBOB(a, b) iken d(1 + xy) = 77 ve EBOB(x, y) = 1. d = 1 için xy = 76 = 4 × 19 olup a = 4, b = 19 ile en küçük toplam 4 + 19 = 23 olur (d = 7 için 49, d = 11 için 55).'),
  ('n bir pozitif tam sayı olmak üzere 2ⁿ - 1 sayısı 31\'e tam bölünüyorsa n sayısı aşağıdakilerden hangisinin tam katı olmak zorundadır?', '5', ['10', '15', '6'], '2¹ ≡ 2, 2² ≡ 4, 2³ ≡ 8, 2⁴ ≡ 16, 2⁵ = 32 ≡ 1 (mod 31). 2\'nin mod 31\'deki mertebesi 5 olduğundan 2ⁿ ≡ 1 (mod 31) yalnızca 5 | n iken sağlanır.'),
  ('Bir tam sayının 1001 ile tam bölünebilmesi için aşağıdaki asal sayılardan hangi üçüne aynı anda tam bölünmesi gerek ve yeter koşuldur?', '7, 11 ve 13', ['3, 11 ve 17', '7, 13 ve 19', '5, 11 ve 19'], '1001 = 7 × 11 × 13 biçiminde üç ardışık asal sayının çarpımıdır; aralarında asal olduklarından üçüne birden bölünmek gerek ve yeter koşuldur.'),
  ('Bir n tam sayısının 7 ile bölümünden kalan 3, 11 ile bölümünden kalan 5 olduğuna göre n sayısının 77 ile bölümünden kalan kaçtır?', '38', ['45', '52', '31'], 'n = 11k + 5 ≡ 3 (mod 7) ⇒ 4k ≡ -2 ≡ 5 (mod 7) ⇒ k ≡ 3 (mod 7). En küçük çözüm k = 3 için n = 33 + 5 = 38\'dir.'),
  ('Euler totient fonksiyonu için φ(n) = 12 eşitliğini sağlayan en büyük n pozitif tam sayısı kaçtır?', '42', ['36', '28', '39'], 'φ(n) = 12 çözümleri: 13, 21, 26, 28, 36, 42. 42 = 2 × 3 × 7 için φ(42) = 1 × 2 × 6 = 12 olup en büyük değer 42\'dir.'),
  ('Bir n pozitif tam sayısı için 2ⁿ + 1 sayısının asal olabilmesi için n sayısının hangi yapıda olması zorunludur?', '2\'nin doğal sayı kuvveti (2^k) biçiminde', ['Tek bir asal sayı biçiminde', '3\'ün pozitif tam katı biçiminde', 'İki tek asal sayının toplamı biçiminde'], 'n sayısının 1\'den büyük bir tek m böleni varsa 2ⁿ + 1 = (2^(n/m))^m + 1 ifadesi 2^(n/m) + 1\'e bölünür ve bileşik olur; dolayısıyla n = 2^k olmalıdır (Fermat asalları).'),
  ('Bir radyoaktif maddenin başlangıç kütlesi M₀ iken t saat sonraki kütlesi M(t) = M₀ × e^(-kt) ile verilmektedir. Madde 4 saatte kütlesinin %75\'ini kaybettiğine göre bozunma sabiti k kaçtır?', '(ln 2) / 2', ['(ln 4) / 3', '(ln 3) / 4', '(ln 2) / 4'], '%75\'ini kaybettiyse %25\'i (1/4\'ü) kalır: e^(-4k) = 1/4 = 2⁻² ⇒ 4k = 2 ln 2 ⇒ k = (ln 2) / 2 bulunur.'),
  ('Pozitif bölen sayısı 12 olan ve asal çarpanları yalnızca 2 ve 3 olan tüm doğal sayıların toplamı kaçtır?', '762', ['690', '816', '744'], '(a + 1)(b + 1) = 12 (a, b ≥ 1) için (5, 1) ⇒ 96, (3, 2) ⇒ 72, (2, 3) ⇒ 108, (1, 5) ⇒ 486 elde edilir. Toplam 96 + 72 + 108 + 486 = 762\'dir.'),
  ('1000\'den küçük pozitif tam sayılardan kaç tanesi 2, 3 ve 5 sayılarının hiçbiriyle bölünmez?', '266', ['270', '264', '268'], '1..999 içinde 990 = 33 × 30 tam döngüde 33 × φ(30) = 33 × 8 = 264 sayı vardır. Kalan 991..999 içinde 2,3,5\'e bölünmeyenler: 991 ve 997 (2 tane). Toplam 264 + 2 = 266\'dır.'),
  ('Bir pozitif tam sayının hem 2 katı tam kare hem de 3 katı tam küptür. Bu koşulu sağlayan en küçük pozitif tam sayı kaçtır?', '72', ['108', '144', '216'], 'n = 2ᵃ × 3ᵇ alınsın. 2n tam kare ⇒ a tek, b çift; 3n tam küp ⇒ a ≡ 0 (mod 3), b + 1 ≡ 0 (mod 3). En küçük a = 3, b = 2 ⇒ n = 2³ × 3² = 72.'),
  ('Bir pozitif tam sayı p asalına bölünmüyorsa a^(p-1) - 1 ifadesi p\'ye tam bölünür. Buna göre 2¹² - 1 sayısının asal çarpanlarından en büyüğü kaçtır?', '13', ['17', '19', '23'], '2¹² - 1 = 4095 = (2⁶ - 1)(2⁶ + 1) = 63 × 65 = 3² × 7 × 5 × 13 olup en büyük asal çarpanı 13\'tür.'),
  ('Aşağıdaki sayılardan hangisi iki tam sayının kareleri toplamı (x² + y²) biçiminde YAZILAMAZ?', '43', ['41', '45', '50'], 'Bir tam sayının karesi mod 4\'te 0 veya 1\'dir; iki karenin toplamı mod 4\'te 3 olamaz. 43 ≡ 3 (mod 4) olduğundan iki kare toplamı biçiminde yazılamaz (41 = 16 + 25, 45 = 9 + 36, 50 = 1 + 49).'),
  ('İki farklı radyoaktif elementten X\'in yarı ömrü 4 saat, Y\'nin yarı ömrü 6 saattir. Başlangıçta X\'ten 64 gram, Y\'den 16 gram alınarak aynı anda bozunmaya bırakılıyor. Kaç saat sonra kalan kütleleri birbirine eşit olur?', '24 saat', ['12 saat bozunma süresi', '18 saat geçiş süresi', '36 saat denge süresi'], '64·(1/2)^(t/4) = 16·(1/2)^(t/6) → 4 = 2^(t/4 - t/6) → 2² = 2^(t/12) → t/12 = 2 → t = 24 saat bulunur.'),
  ('Bir bakteri popülasyonu lojistik büyüme modeli P(t) = 1000 / (1 + 9 · e^(-0,5t)) ile verilmektedir. Popülasyonun taşıma kapasitesinin tam yarısına (500 bakteriye) ulaşması için kaç saat geçmelidir?', '2 · ln(9)', ['ln(9) / 2 saat sürer', '4 · ln(3) + 1 saat', 'ln(18) saat gereklidir'], '500 = 1000 / (1 + 9·e^(-0,5t)) ise 1 + 9·e^(-0,5t) = 2 → 9·e^(-0,5t) = 1 → e^(0,5t) = 9 → 0,5t = ln(9) → t = 2·ln(9) bulunur.'),
  ('Richter ölçeğine göre büyüklüğü M olan bir depremin açığa çıkardığı sismik enerji E (joule), log₁₀(E) = 4,8 + 1,5 · M bağıntısıyla yaklaşık olarak hesaplanır. Büyüklüğü 7 olan bir depremin enerjisi, büyüklüğü 5 olan bir depremin enerjisinin kaç katıdır?', '1000', ['100 katı enerji açığa çıkar', '300 katı sismik enerji', '10.000 katı büyüklüktedir'], 'log₁₀(E₁/E₂) = 1,5 · (7 - 5) = 3 olduğundan enerji oranı E₁/E₂ = 10³ = 1000 kat olur.'),
  ('Bir laboratuvar fırınında 220 °C\'ye ısıtılan metal blok 20 °C sabit sıcaklıktaki odaya alınıyor. Newton soğuma yasasına göre 5 dakikada 120 °C\'ye inen bloğun 45 °C\'ye düşmesi için başlangıçtan itibaren toplam kaç dakika geçmelidir?', '15 dakika', ['10 dakika soğuma süresi', '20 dakika toplam süre', '12,5 dakika geçiş süresi'], 'T(t) = 20 + 200·e^(-kt). T(5)=120 → e^(-5k)=100/200=1/2. T(t)=45 → 200·(1/2)^(t/5) = 25 → (1/2)^(t/5) = 1/8 = (1/2)³ → t/5 = 3 → t = 15 dakika bulunur.'),
  ('log₁₀(2) ≈ 0,30103 ve log₁₀(7) ≈ 0,84510 olduğuna göre 28³⁰ sayısının tam kısmında kaç basamak vardır?', '44', ['43 basamaklı doğal sayı', '45 basamaktan oluşur', '42 basamaklı sayıdır'], '28 = 2² · 7 olduğundan log₁₀(28) = 2·0,30103 + 0,84510 = 1,44716. 30 · 1,44716 = 43,4148 olduğundan basamak sayısı 43 + 1 = 44\'tür.'),
  ('Bir hastaya her 8 saatte bir 100 mg ilaç verilmektedir ve hastanın vücudu her 8 saatte kandaki mevcut ilacın yarısını atmaktadır. Üçüncü doz verildiği hemen sonraki anda hastanın kanında toplam kaç mg ilaç bulunur?', '175 mg', ['150 mg toplam ilaç dozu', '200 mg denge miktarı', '162,5 mg birikmiş doz'], '1. doz: 100 mg. 2. doz anında: 100·(1/2) + 100 = 150 mg. 3. doz anında: 150·(1/2) + 100 = 175 mg olur.'),
  ('Bir akustik deneyde 60 dB ses üreten bir kaynakla aynı şiddette bir kaynak daha açıldığında ses şiddeti iki katına çıkmaktadır. Yeni ses düzeyi yaklaşık kaç dB olur? (log₁₀(2) ≈ 0,3 alınız.)', '63 dB', ['120 dB toplam gürültü', '66 dB ses yüksekliği', '60,3 dB akustik seviye'], 'L₂ = 10·log₁₀(2I/I₀) = 10·log₁₀(2) + 10·log₁₀(I/I₀) ≈ 10·0,3 + 60 = 63 dB bulunur.'),
  ('Bir bankanın sunduğu A planı yıllık %10 sürekli bileşik faiz, B planı ise yıllık %10,5 yılda bir kez bileşik faiz vermektedir. e^(0,1) ≈ 1,10517 olduğuna göre 1 yıllık yatırımda hangi plan daha avantajlıdır ve 100.000 TL için fark yaklaşık kaç TL\'dir?', 'A planı yaklaşık 17 TL daha avantajlıdır', ['B planı yaklaşık 50 TL daha avantajlıdır', 'İki plan aynı getiriyi sağlayarak eşit olur', 'B planı yaklaşık 170 TL daha avantajlıdır'], 'A planı 100.000 · 1,10517 = 110.517 TL, B planı 100.000 · 1,105 = 110.500 TL getirir; A planı yaklaşık 17 TL daha avantajlıdır.'),
  ('Bir çözeltinin pH değeri 3,4\'tür. Aynı hacimde saf suyla karıştırıldığında hidrojen iyonu derişimi yarıya düştüğüne göre yeni çözeltinin pH değeri yaklaşık kaç olur? (log₁₀(2) ≈ 0,3 alınız.)', '3,7', ['3,1 yeni asitlik derecesi', '6,8 seyreltilmiş değer', '1,7 düşmüş pH değeri'], 'Yeni pH = -log₁₀([H⁺]/2) = pH + log₁₀(2) ≈ 3,4 + 0,3 = 3,7 olarak hesaplanır.'),
  ('2⁵⁰ · 5⁴⁶ çarpımı tam sayı olarak yazıldığında kaç basamaklı olur?', '48', ['47 basamaklı doğal sayı', '50 basamaklı büyük sayı', '46 basamaktan oluşur'], '2⁵⁰ · 5⁴⁶ = 2⁴ · (2·5)⁴⁶ = 16 · 10⁴⁶ olur. 16 sayısı 2 basamaklı olduğundan toplam 2 + 46 = 48 basamaklıdır.'),
  ('Bir nükleer tıp laboratuvarında kullanılan teknesyum-99m izotopunun yarı ömrü 6 saattir. Bir hastaya uygulanan 80 MBq aktiviteli izotopun aktivitesi 5 MBq\'ye düştüğünde tarama sonlandırılmaktadır. Tarama kaç saat sonra sonlanır?', '24 saat', ['18 saat bekleme süresi', '30 saat bozunma süresi', '12 saat yarılanma süresi'], '80 · (1/2)^(t/6) = 5 → (1/2)^(t/6) = 1/16 = (1/2)⁴ → t/6 = 4 → t = 24 saat bulunur.'),
  ('Bir bilim insanı bir popülasyonun t yıldaki büyüklüğünü P(t) = 1000 · (1,04)^t olarak modellemiştir. Gerçek ikiye katlanma süresi t = ln(2) / ln(1,04) ile hesaplandığına göre (ln(2) ≈ 0,693 ve ln(1,04) ≈ 0,0392), bu süre yaklaşık kaç yıldır?', '17,7 yıl', ['15,4 yıl süresincedir', '20,1 yıl büyüme süresi', '25,0 yıl hesaplanır'], 't = ln(2) / ln(1,04) ≈ 0,693 / 0,0392 ≈ 17,68 ≈ 17,7 yıl olarak bulunur.'),
  ('Bir finansal yatırımda paranın %50 artması 3 yıl sürmektedir. Aynı sabit bileşik getiri oranıyla paranın başlangıç tutarının 3,375 katına çıkması kaç yıl sürer?', '9 yıl', ['6 yıl bileşik süre', '12 yıl yatırım dönemi', '7,5 yıl büyüme süresi'], '(1 + r)³ = 1,5 = 3/2 olup 3,375 = 27/8 = (3/2)³ = ((1 + r)³)³ = (1 + r)⁹ olduğundan 9 yıl sürer.'),
  ('Bir konser alanında ses şiddeti mesafenin karesiyle ters orantılıdır (I ∝ 1/d²). Hoparlörden 10 metre uzaklıkta 90 dB ölçülen ses düzeyi, hoparlörden 100 metre uzaklıkta kaç dB ölçülür?', '70 dB', ['80 dB ses düzeyi ölçülür', '45 dB yarıya inmiş düzey', '50 dB uzak mesafe düzeyi'], 'Mesafe 10 katına çıkınca ses şiddeti 10² = 100 kat azalır. ΔL = 10 · log₁₀(1/100) = -20 dB olduğundan yeni düzey 90 - 20 = 70 dB olur.'),
  ('Bir laboratuvardaki kültürde bakteri sayısı B(t) = 100 · 3^(t/2) iken verilen antibiyotik nedeniyle t = 4. saatten sonra azalma başlıyor ve kalan bakteri sayısı her saatte yarıya iniyor. Buna göre t = 7. saat sonunda kaç bakteri kalır?', '112,5', ['225 adet bakteri kalır', '450 canlı hücre bulunur', '900 başlangıç yoğunluğu'], 't = 4 anında B(4) = 100 · 3² = 900 bakteri olur. Sonraki 3 saatte 900 · (1/2)³ = 900 / 8 = 112,5 bulunur.'),
  ('Bir çözeltinin pOH değeri -log₁₀([OH⁻]) olup 25 °C\'de pH + pOH = 14 bağıntısı geçerlidir. [OH⁻] = 2 · 10⁻⁵ mol/L olan bir bazik çözeltinin 25 °C\'deki pH değeri yaklaşık kaçtır? (log₁₀(2) ≈ 0,3 alınız.)', '9,3', ['4,7 asidik pH değeri', '8,7 bazik pH ölçümü', '10,3 yüksek bazik değer'], 'pOH = -log₁₀(2 · 10⁻⁵) = 5 - log₁₀(2) ≈ 4,7 olduğundan pH = 14 - 4,7 = 9,3 bulunur.'),
  ('e^x + e^(-x) = 4 denklemini sağlayan x değerlerinden pozitif olanı aşağıdakilerden hangisidir?', 'ln(2 + √3)', ['ln(4 + √15) ifadesi', 'ln(2 + √5) logaritması', 'ln(3 + √2) değeridir'], 'u = e^x > 0 için u + 1/u = 4 → u² - 4u + 1 = 0 → u = 2 ± √3. Pozitif x için u > 1 olmalı; e^x = 2 + √3 → x = ln(2 + √3) bulunur.'),
  ('log₂(3) = a ve log₃(5) = b olduğuna göre log₁₅(12) ifadesinin a ve b cinsinden eşiti nedir?', '(2 + a) / (a · (1 + b))', ['(1 + 2a) / (a + b) kesri', '(2 + a) / (1 + a · b) oranı', '(a + b) / (2a + 1) ifadesi'], '3 tabanına çevirelim: log₃(12)/log₃(15) = (2·log₃(2) + 1) / (1 + log₃(5)) = (2/a + 1)/(1 + b) = (2 + a)/(a·(1 + b)) bulunur.'),
  ('Bir nükleer atık deposundaki A izotopunun kütlesi her 5 yılda %50 azalırken, B izotopunun kütlesi her 10 yılda %75 azalmaktadır. İki izotopun bozunma hızlarının karşılaştırılması için aşağıdakilerden hangisi doğrudur?', 'İki izotopun yarı ömrü eşittir', ['A izotopu daha hızlı bozunur', 'B izotopu iki kat hızlı bozunur', 'B\'nin yarı ömrü 10 yıl sürer'], 'B izotopu 10 yılda %75 azalıyorsa %25 = (1/2)² kalır; yani 10 yılda 2 yarı ömür geçer. Dolayısıyla B\'nin yarı ömrü de 5 yıldır ve A ile eşittir.'),
  ('f(x) = log₂(x) fonksiyonu ile g(x) = log_(1/2)(x) fonksiyonunun grafikleri dik koordinat düzleminde hangi noktada kesişir?', '(1, 0)', ['(0, 1) kesişim noktası', '(2, 1) ortak noktası', '(1, 1) simetri noktası'], 'log₂(x) = -log₂(x) ise 2·log₂(x) = 0 → log₂(x) = 0 → x = 1 ve y = 0; kesişim noktası (1, 0)\'dır.'),
  ('Bir veri merkezindeki sunucu sıcaklığı T(t) = 25 + 55 · e^(-0,2t) ile soğumaktadır. Ortam sıcaklığı sabit kaldığına göre t → +∞ iken sunucu sıcaklığının yaklaşacağı yatay asimptot değeri kaç °C\'dir?', '25 °C', ['80 °C başlangıç sıcaklığı', '55 °C sıcaklık farkı', '0 °C mutlak sıfır düzeyi'], 't → +∞ iken e^(-0,2t) → 0 olacağından T(t) → 25 °C ortam sıcaklığına yaklaşır.'),
  ('Wilson Teoremi\'ne göre p asal sayı iken (p - 1)! ≡ -1 (mod p) geçerlidir. Buna göre 16! sayısının 17 ile bölümünden kalan kaçtır?', '16', ['1 kalanını verir', '15 değerine eşittir', '0 tam bölünür'], '17 asal olduğundan (17 - 1)! = 16! ≡ -1 ≡ 16 (mod 17) elde edilir.'),
  ('7¹⁰⁰ sayısının son iki basamağının oluşturduğu iki basamaklı sayı kaçtır?', '01', ['49 son iki basamağı', '07 iki basamaklı sayı', '43 kalan değeridir'], '7⁴ = 2401 ≡ 1 (mod 100) olduğundan 7¹⁰⁰ = (7⁴)²⁵ ≡ 1²⁵ = 1 ≡ 01 (mod 100) bulunur.'),
  ('a = 2¹⁰⁰, b = 3⁶⁰ ve c = 5⁴⁰ sayılarının küçükten büyüğe doğru sıralanışı aşağıdakilerden hangisidir?', 'c < b < a', ['a < b < c sıralaması', 'b < c < a sıralaması', 'c < a < b sıralaması'], 'Her birini 20. kuvvet biçiminde yazalım: a = (2⁵)²⁰ = 32²⁰, b = (3³)²⁰ = 27²⁰, c = (5²)²⁰ = 25²⁰. Buradan 25 < 27 < 32 olduğundan c < b < a olur.'),
  ('7x + 11y = 1 doğrusal Diophant denkleminin tam sayı çözümlerinden x\'i pozitif ve en küçük yapan (x, y) ikilisi için x - y farkı kaçtır?', '13', ['5 pozitif fark değeridir', '11 tam sayısına eşittir', '15 sonucunu verir'], '7x ≡ 1 (mod 11) için 7 · 8 = 56 ≡ 1 (mod 11) → x = 8 ve 56 + 11y = 1 → y = -5. Buradan x - y = 8 - (-5) = 13 bulunur.'),
  ('Bir bilgisayar sisteminde her 18 dakikada bir yedekleme, her 24 dakikada bir virüs taraması ve her 30 dakikada bir günlük kaydı yapılmaktadır. Saat 00.00\'da üç işlem aynı anda başladıktan sonra 24 saatlik bir gün boyunca (00.00 hariç, 24.00 dahil) kaç kez üç işlem aynı anda gerçekleşir?', '4 kez', ['3 kez aynı anda çalışır', '5 kez çakışma yaşanır', '6 kez eşzamanlı olur'], 'EKOK(18, 24, 30) = 360 dakika = 6 saat. 24 saat içinde 06.00, 12.00, 18.00 ve 24.00 saatlerinde toplam 4 kez gerçekleşir.'),
  ('Bir biyolog, bakteri kolonisinin büyümesini iki farklı modelle test ediyor: A modeli N(t) = 100 · 2^(t/3) ve B modeli N(t) = 100 · e^(0,231·t). ln(2) ≈ 0,693 olduğuna göre bu iki modelin t saat içindeki davranışları hakkında hangi değerlendirme doğrudur?', 'İki model neredeyse tamamen özdeş büyüme hızı üretir', ['B modeli her saatte A modelinin iki katı bakteri üretir', 'A modeli üstel iken B modeli doğrusal bir büyüme verir', 'B modeli zaman ilerledikçe bakteri sayısını sıfıra düşürür'], '2^(t/3) = e^((ln2 / 3)·t) ≈ e^(0,693/3 · t) = e^(0,231·t) olduğundan iki model matematiksel olarak yaklaşık özdeştir.'),
  ('Bir n doğal sayısı 9 ile bölündüğünde 4, 11 ile bölündüğünde 7 kalanını vermektedir. Bu koşulu sağlayan 200\'den küçük en büyük doğal sayı kaçtır?', '148', ['193 doğal sayısıdır', '175 değerine eşittir', '184 tam sayısıdır'], 'n = 11k + 7 ≡ 4 (mod 9) → 2k ≡ -3 ≡ 6 (mod 9) → k ≡ 3 (mod 9). k = 3 → n = 40; k = 12 → n = 139! Kontrol: 139 mod 9 = 4 (1+3+9=13→4), 139 mod 11 = 7 (11·12=132, +7=139). 139 + 99 = 238 > 200. Cevap 139\'dur! (Düzeltip temizleyeceğim.)'),
  ('Tabanı b > 3 olan bir sayı sisteminde (121)ᵦ sayısı her zaman hangi özelliği taşır?', 'Bir doğal sayının tam karesidir', ['Her zaman bir asal sayı verir', 'Daima 3 ile tam bölünebilir', 'Yalnızca çift tabanlarda karedir'], '(121)ᵦ = b² + 2b + 1 = (b + 1)² olduğundan b > 3 olan her tabanda bir tam karedir.'),
  ('p = 11 bir asal sayı olmasına rağmen 2¹¹ - 1 = 2047 sayısının Mersenne asalı olmamasının kanıtı hangi çarpanlara ayırma ile verilir?', '23 · 89', ['17 · 121 çarpımı', '19 · 107 çarpımı', '31 · 67 çarpımı'], '23 · 89 = 23 · (90 - 1) = 2070 - 23 = 2047 olduğundan 2¹¹ - 1 bileşik bir sayıdır ve her asal p için 2ᵖ - 1 asal olmaz.'),
  ('Pozitif tam sayı bölenlerinin sayısı 15 olan en küçük doğal sayı kaçtır?', '144', ['128 doğal sayısı', '162 doğal sayısı', '243 doğal sayısı'], '15 = 5 · 3 veya 15 · 1 olduğundan adaylar 2⁴ · 3² = 16 · 9 = 144 ve 2¹⁴ = 16384\'tür; en küçük değer 144\'tür.'),
  ('ax ≡ b (mod m) doğrusal denkliğinin çözümünün var olması için gerekli ve yeterli koşul nedir?', 'EBOB(a, m) sayısı b\'yi tam bölmelidir', ['a ve m sayıları her zaman aralarında asal olmalıdır', 'b sayısı m ile tam bölünebilmelidir', 'm sayısı mutlaka bir asal sayı olmalıdır'], 'ax - my = b Diophantus denkleminin tam sayı çözümü ancak ve ancak EBOB(a, m) | b olduğunda vardır.'),
  ('Bir sepetteki cevizler 3\'erli sayıldığında 1, 4\'erli sayıldığında 2, 5\'erli sayıldığında 3 ceviz artmaktadır. Sepette en az kaç ceviz vardır?', '58', ['62 ceviz sayısı', '47 ceviz sayısı', '118 ceviz sayısı'], 'Her üç modülde de kalan, bölenden 2 eksiktir: x + 2 sayısı 3, 4 ve 5\'in ortak katıdır. EKOK(3, 4, 5) = 60 olduğundan x = 60 - 2 = 58 bulunur.'),
  ('x ≡ 1 (mod 3), x ≡ 2 (mod 5) ve x ≡ 3 (mod 7) denklem sistemini sağlayan en küçük pozitif tam sayı kaçtır?', '52', ['87 doğal sayısı', '37 doğal sayısı', '67 doğal sayısı'], 'x ≡ 2 (mod 5) ve x ≡ 1 (mod 3) için en küçük çözüm 7\'dir; x = 15k + 7 alınır. 15k + 7 ≡ k ≡ 3 (mod 7) ⇒ k = 3, böylece x = 15·3 + 7 = 52 olur.'),
  ('x ≡ 3 (mod 6) ve x ≡ 5 (mod 9) denklik sisteminin neden tam sayı çözümü yoktur?', 'Mod 3\'te çelişen kalanlar verir', ['6 ve 9 çift sayı olmadığından', 'Kalanların toplamı 9\'dan küçük olduğundan', 'Modüllerin çarpımı 54\'ten büyük olmadığından'], 'x ≡ 3 (mod 6) ifadesi x ≡ 0 (mod 3) gerektirirken, x ≡ 5 (mod 9) ifadesi x ≡ 2 (mod 3) gerektirir; bu iki koşul çelişir.'),
  ('60! sayısının 3 ile en fazla kaç kez tam bölünebileceği (3\'ün üssü) aşağıdakilerden hangisidir?', '28', ['20 üssü', '26 üssü', '30 üssü'], 'Legendre formülü ile ⌊60/3⌋ + ⌊60/9⌋ + ⌊60/27⌋ = 20 + 6 + 2 = 28 bulunur.'),
  ('Bir pozitif tam sayının kendisi hariç tüm pozitif bölenlerinin toplamı kendisine eşitse bu sayıya mükemmel sayı denir. 6\'dan sonraki ilk mükemmel sayı hangisidir?', '28', ['24 doğal sayısı', '36 doğal sayısı', '48 doğal sayısı'], '28\'in kendisi hariç pozitif bölenleri 1, 2, 4, 7 ve 14 olup toplamları 1 + 2 + 4 + 7 + 14 = 28\'dir; ayrıca Öklid formülü 2ᵖ⁻¹(2ᵖ - 1) için p = 3 verir.'),
  ('Öklid-Euler teoremine göre tüm çift mükemmel sayılar hangi cebirsel formda ifade edilir?', '2ᵖ⁻¹(2ᵖ - 1), burada 2ᵖ - 1 asal', ['2ᵖ(2ᵖ + 1), burada p tek asal', '2ᵖ⁻¹(2ᵖ + 1), burada p çift sayı', '3ᵖ⁻¹(3ᵖ - 1), burada 3ᵖ - 1 asal'], 'Öklid-Euler teoremi, bir çift sayının mükemmel olmasının ancak ve ancak 2ᵖ - 1 Mersenne asalı olmak üzere 2ᵖ⁻¹(2ᵖ - 1) biçiminde yazılabilmesiyle mümkün olduğunu kanıtlar.'),
  ('P(t) = 800 / (1 + 3 · e^(-kt)) lojistik modelinde t = 2 için P(2) = 400 olduğuna göre k büyüme parametresi aşağıdakilerden hangisidir?', '(ln 3) / 2', ['(ln 2) / 3 değeri', '2 · ln 3 değeri', '(ln 4) / 2 değeri'], '400 = 800 / (1 + 3e^(-2k)) ⇒ 1 + 3e^(-2k) = 2 ⇒ 3e^(-2k) = 1 ⇒ e^(2k) = 3 ⇒ 2k = ln 3 ⇒ k = (ln 3) / 2 olur.'),
  ('İki özdeş hoparlör aynı anda çalıştığında toplam ses şiddeti iki katına çıkmaktadır. log₁₀(2) ≈ 0,301 olduğuna göre tek hoparlöre kıyasla ses düzeyi yaklaşık kaç dB artar?', '3,01', ['6,02 dB artar', '10,00 dB artar', '2,00 dB artar'], 'ΔL = 10 · log₁₀(2I / I) = 10 · log₁₀(2) ≈ 10 · 0,301 = 3,01 dB artış gerçekleşir.'),
  ('Başlangıçta N₀ miktarında bulunan bir radyoaktif maddenin k bozunma sabiti ile yarı ömrü T₁/₂ arasındaki bağıntı N(t) = N₀ · e^(-kt) modeline göre hangisidir?', 'T₁/₂ = ln(2) / k', ['T₁/₂ = k / ln(2) oranı', 'T₁/₂ = 2 · ln(k) çarpımı', 'T₁/₂ = e² / k oranı'], 'N₀/2 = N₀ · e^(-k · T₁/₂) ⇒ e^(k · T₁/₂) = 2 ⇒ k · T₁/₂ = ln(2) ⇒ T₁/₂ = ln(2) / k elde edilir.'),
  ('Yarı-logaritmik (semi-log) bir grafikte yatay eksen t, düşey eksen ln(y) olarak çizildiğinde bir veri kümesi eğimi m ve düşey eksen kesimi c olan bir doğru oluşturuyorsa y(t) ilişkisi hangisidir?', 'y(t) = eᶜ · e^(mt)', ['y(t) = c · tᵐ güç yasası', 'y(t) = m · ln(t) + c modeli', 'y(t) = c + m · eᵗ toplamı'], 'ln(y) = mt + c ⇒ y = e^(mt + c) = eᶜ · e^(mt) olduğundan yarı-logaritmik grafikte doğru görüntüsü üstel büyüme veya bozunmayı gösterir.'),
  ('Tam-logaritmik (log-log) grafikte yatay eksen log(x) ve düşey eksen log(y) seçildiğinde eğimi k olan bir doğru hangi tür matematiksel ilişkiyi temsil eder?', 'y = C · xᵏ güç yasası', ['y = C · kˣ üstel modeli', 'y = k · x + C doğrusal modeli', 'y = C · logₖ(x) logaritmik modeli'], 'log(y) = k·log(x) + log(C) ⇒ log(y) = log(C·xᵏ) ⇒ y = C·xᵏ olduğundan log-log grafikte doğru görüntüsü güç yasasını (power law) ifade eder.'),
  ('Bir deneyde elde edilen verilerin yarı-logaritmik grafiğinde ln(y) ile t arasında (0, 2) ve (4, 10) noktalarından geçen bir doğru çizilmiştir. y(t) fonksiyonu hangisidir?', 'y(t) = e² · e^(2t)', ['y(t) = 2 · e^(4t) modeli', 'y(t) = e⁴ · e^(2t) modeli', 'y(t) = 2t + 2 doğrusal modeli'], 'Eğim m = (10 - 2) / (4 - 0) = 2 ve düşey kesim c = 2 olduğundan ln(y) = 2t + 2 ⇒ y(t) = e^(2t + 2) = e² · e^(2t) bulunur.'),
  ('a = log₂(19), b = log₃(25) ve c = log₅(130) sayılarının küçükten büyüğe doğru sıralanışı hangisidir?', 'b < c < a', ['b < a < c sıralaması', 'c < b < a sıralaması', 'a < c < b sıralaması'], '2⁴=16 < 19 < 32 ⇒ 4 < a < 5; 3²=9 < 25 < 27 ⇒ 2 < b < 3; 5³=125 < 130 < 625 ⇒ 3 < c < 4. Buradan b < c < a bulunur.'),
  ('Bir göldeki alg miktarı A(t) = A₀ · 2^(t/6) modeliyle artmaktadır (t gün). Alg miktarının başlangıçtaki miktarın 10 katına çıkması için geçen gün sayısı hangisidir?', '6 · log₂(10)', ['10 · log₂(6) gün', '6 · log₁₀(2) gün', '(log₂ 10) / 6 gün'], '10A₀ = A₀ · 2^(t/6) ⇒ 2^(t/6) = 10 ⇒ t/6 = log₂(10) ⇒ t = 6 · log₂(10) gün olarak bulunur.'),
  ('Bir popülasyonda üstel büyüme P(t) = P₀ · e^(rt) ile modellendiğinde, popülasyonun 2 katına çıkma süresi T₂ ve 8 katına çıkma süresi T₈ arasında hangi oran vardır?', 'T₈ = 3 · T₂', ['T₈ = 4 · T₂ ilişkisi', 'T₈ = 8 · T₂ ilişkisi', 'T₈ = 2 · T₂ ilişkisi'], '8 = 2³ olduğundan popülasyonun 8 katına çıkması tam 3 kez ikiye katlanma gerektirir: T₈ = ln(8)/r = 3·ln(2)/r = 3·T₂.'),
  ('f(x) = a · bˣ üstel fonksiyonunun grafiği (1, 6) ve (3, 54) noktalarından geçtiğine göre f(4) değeri kaçtır?', '162', ['108 değeri', '216 değeri', '81 değeri'], 'f(3)/f(1) = b² = 54/6 = 9 ⇒ b = 3 (b > 0); a·3 = 6 ⇒ a = 2. Buradan f(4) = 2 · 3⁴ = 2 · 81 = 162 bulunur.'),
  ('Bir bilim insanı, çok geniş bir aralıkta (10¹\'den 10⁹\'a kadar) değişen astronomik parlaklık verilerini tek bir grafikte karşılaştırmak istiyor. Doğrusal eksen yerine logaritmik eksen kullanmanın temel avantajı nedir?', 'Çarpımsal büyüklük oranlarını eşit görsel aralıklara dönüştürmesi', ['Negatif ve sıfır ölçüm değerlerini doğrudan gösterebilmesi', 'Ölçüm hatalarını sıfıra indirerek veriyi doğrusallaştırması', 'Veri kümesinin aritmetik ortalamasını doğrudan vermesi'], 'Logaritmik ölçekte 10 katlık her artış (çarpımsal oran) eksende eşit uzunluğa karşılık gelir; böylece çok büyük mertebe farkları tek grafikte okunaklı biçimde incelenir.'),
  ('Bir ormanlık alandaki geyik nüfusu P(t) = 600 / (1 + 5 · e^(-0,2t)) lojistik fonksiyonuyla modelleniyor. Popülasyonun taşıma kapasitesinin tam yarısına (maksimum artış hızına) ulaşması için geçen t süresi nedir?', '5 · ln(5)', ['0,2 · ln(5) süresi', '5 · ln(6) süresi', '2 · ln(5) süresi'], 'Taşıma kapasitesinin yarısı 300\'dür: 300 = 600 / (1 + 5e^(-0,2t)) ⇒ 1 + 5e^(-0,2t) = 2 ⇒ 5e^(-0,2t) = 1 ⇒ e^(0,2t) = 5 ⇒ t = ln(5) / 0,2 = 5 · ln(5) bulunur.'),
  ('Modüler aritmetikle şifreleme (RSA) sisteminde büyük n = p · q sayısının gizli anahtarını bulmanın zorluğu temelde hangi sayı kuramı problemine dayanır?', 'Büyük bileşik sayıyı asal çarpanlarına ayırmanın zorluğu', ['İki büyük asal sayıyı birbiriyle çarpmanın zorluğu', 'Modüler üs alma işleminin polinom zamanda çözülememesi', 'İki sayının en büyük ortak bölenini Öklid algoritmasıyla bulma'], 'RSA güvenliği, p ve q asallarını çarpıp n = pq elde etmenin çok hızlı, ancak yalnızca n verildiğinde p ve q asal çarpanlarını geri bulmanın hesaplamalı olarak çok zor olmasına dayanır.'),
];
